const cfg = $('Config').first().json;
const windowHours = cfg.windowHours;
const cutoff = Date.now() - windowHours * 3600000;

const workflows = $('Get all workflows').all().map((i) => i.json);
const executions = $('Get recent executions').all().map((i) => i.json);

const toMs = (value) => {
  const t = value ? new Date(value).getTime() : NaN;
  return Number.isFinite(t) ? t : null;
};
const p95 = (durations) => {
  if (!durations.length) return null;
  const sorted = [...durations].sort((a, b) => a - b);
  return sorted[Math.ceil(0.95 * sorted.length) - 1];
};

const stats = new Map();
for (const wf of workflows) {
  stats.set(wf.id, { id: wf.id, name: wf.name, runs: 0, success: 0, errors: 0, durations: [], lastRunMs: null });
}

for (const exec of executions) {
  const wf = stats.get(exec.workflowId);
  if (!wf) continue;

  const startedAt = toMs(exec.startedAt);
  if (startedAt !== null && (wf.lastRunMs === null || startedAt > wf.lastRunMs)) {
    wf.lastRunMs = startedAt;
  }
  if (startedAt === null || startedAt < cutoff) continue;

  wf.runs++;
  if (exec.status === 'success') wf.success++;
  else if (exec.status === 'error') wf.errors++;

  const stoppedAt = toMs(exec.stoppedAt);
  if (stoppedAt !== null && stoppedAt >= startedAt) wf.durations.push(stoppedAt - startedAt);
}

const buckets = [...stats.values()];
const perWorkflow = buckets.map((wf) => ({
  id: wf.id,
  name: wf.name,
  runs: wf.runs,
  errors: wf.errors,
  successRate: wf.runs ? Math.round((wf.success / wf.runs) * 100) : null,
  p95Ms: p95(wf.durations),
  lastRunAt: wf.lastRunMs ? new Date(wf.lastRunMs).toISOString() : null,
}));

const runs = buckets.reduce((sum, wf) => sum + wf.runs, 0);
const success = buckets.reduce((sum, wf) => sum + wf.success, 0);
const errors = buckets.reduce((sum, wf) => sum + wf.errors, 0);

return [{ json: {
  generatedAt: new Date().toISOString(),
  windowHours,
  workflowsTotal: workflows.length,
  windowTruncated: executions.length >= cfg.executionLimit,
  executionLimit: cfg.executionLimit,
  fleet: { runs, errors, successRate: runs ? Math.round((success / runs) * 100) : null },
  perWorkflow,
} }];

const buffer = $('Config').first().json.scheduleBuffer;
const now = Date.now();

const lastRunById = new Map(
  $('Aggregate metrics').first().json.perWorkflow.map((wf) => [wf.id, wf.lastRunAt]),
);

const UNIT_MS = {
  seconds: 1000, minutes: 60000, hours: 3600000,
  days: 86400000, weeks: 604800000, months: 2592000000,
};

const periodMs = (interval) => {
  const field = interval.field ?? 'days';
  const unit = UNIT_MS[field];
  if (!unit) return null;
  return Number(interval[`${field}Interval`] ?? 1) * unit;
};

const findings = [];
for (const item of $('Get all workflows').all()) {
  const wf = item.json;
  if (!wf.active) continue;

  const periods = (wf.nodes ?? [])
    .filter((node) => node.type === 'n8n-nodes-base.scheduleTrigger')
    .flatMap((node) => node.parameters?.rule?.interval ?? [])
    .map(periodMs)
    .filter((period) => period > 0);
  if (!periods.length) continue;

  const maxGapMs = Math.round(Math.min(...periods) * buffer);
  const lastRunAt = lastRunById.get(wf.id) ?? null;
  const lastRunMs = lastRunAt ? new Date(lastRunAt).getTime() : null;

  if (lastRunMs === null || now - lastRunMs > maxGapMs) {
    findings.push({
      id: wf.id,
      name: wf.name,
      reason: lastRunMs === null ? 'no execution on record' : 'overdue since last run',
      lastRunAt,
    });
  }
}

return [{ json: { findings } }];

const cfg = $('Config').first().json;
const agg = $('Aggregate metrics').first().json;
const stalledIds = new Set($('Detect stalled schedules').first().json.findings.map((wf) => wf.id));

const targetP95Ms = cfg.targetP95Seconds * 1000;

const perWorkflow = agg.perWorkflow.map((wf) => {
  const breachReasons = [];
  const hasRuns = wf.runs > 0;

  if (hasRuns && wf.successRate !== null && wf.successRate < cfg.targetSuccessRate) {
    breachReasons.push('success');
  }
  if (wf.p95Ms !== null && wf.p95Ms > targetP95Ms) {
    breachReasons.push('latency');
  }
  if (stalledIds.has(wf.id)) {
    breachReasons.push('availability');
  }

  const evaluated = hasRuns || stalledIds.has(wf.id);

  return {
    id: wf.id,
    name: wf.name,
    runs: wf.runs,
    errors: wf.errors,
    successRate: wf.successRate,
    p95Ms: wf.p95Ms,
    evaluated,
    slaStatus: evaluated ? (breachReasons.length ? 'breached' : 'met') : 'skipped',
    breachReasons,
  };
});

const evaluatedList = perWorkflow.filter((wf) => wf.evaluated);
const metCount = evaluatedList.filter((wf) => wf.slaStatus === 'met').length;
const breachCount = evaluatedList.filter((wf) => wf.slaStatus === 'breached').length;

return [{ json: {
  generatedAt: agg.generatedAt,
  windowHours: agg.windowHours,
  targets: { successRate: cfg.targetSuccessRate, p95Seconds: cfg.targetP95Seconds },
  fleet: agg.fleet,
  workflowsTotal: agg.workflowsTotal,
  windowTruncated: agg.windowTruncated,
  executionLimit: agg.executionLimit,
  evaluatedCount: evaluatedList.length,
  metCount,
  breachCount,
  fleetSlaMet: evaluatedList.length > 0 && metCount === evaluatedList.length,
  perWorkflow,
} }];

const cfg = $('Config').first().json;
const sla = $('Evaluate SLA').first().json;

const current = {
  generatedAt: sla.generatedAt,
  targets: sla.targets,
  fleet: sla.fleet,
  evaluatedCount: sla.evaluatedCount,
  metCount: sla.metCount,
  breachCount: sla.breachCount,
  fleetSlaMet: sla.fleetSlaMet,
  perWorkflow: sla.perWorkflow.map((wf) => ({
    id: wf.id,
    name: wf.name,
    successRate: wf.successRate,
    p95Ms: wf.p95Ms,
    slaStatus: wf.slaStatus,
    breachReasons: wf.breachReasons,
  })),
};

const prevRow = $('Get previous snapshot').first().json;
let previous = null;
if (prevRow && prevRow.metrics) {
  try { previous = JSON.parse(prevRow.metrics); } catch { previous = null; }
}

const prevById = new Map((previous?.perWorkflow ?? []).map((wf) => [wf.id, wf]));

const slowdowns = [];
const successDrops = [];
const newlyBreaching = [];
const recovered = [];

for (const wf of current.perWorkflow) {
  const before = prevById.get(wf.id);

  if (before && wf.p95Ms !== null && before.p95Ms) {
    const growthPct = Math.round(((wf.p95Ms - before.p95Ms) / before.p95Ms) * 100);
    if (growthPct > cfg.degradationPct) slowdowns.push({ name: wf.name, growthPct });
  }
  if (before && wf.successRate !== null && before.successRate !== null && before.successRate !== undefined) {
    const dropPp = before.successRate - wf.successRate;
    if (dropPp > cfg.successDropPp) successDrops.push({ name: wf.name, dropPp });
  }

  const wasBreached = before && before.slaStatus === 'breached';
  if (wf.slaStatus === 'breached' && !wasBreached) {
    newlyBreaching.push({ name: wf.name, reasons: wf.breachReasons });
  }
  if (wf.slaStatus === 'met' && wasBreached) {
    recovered.push({ name: wf.name });
  }
}

const fleetSuccessDelta =
  previous?.fleet?.successRate != null && current.fleet.successRate != null
    ? current.fleet.successRate - previous.fleet.successRate
    : null;

return [{ json: {
  runAt: current.generatedAt,
  current,
  hasPrevious: previous !== null,
  fleetSuccessDelta,
  slowdowns,
  successDrops,
  newlyBreaching,
  recovered,
} }];

const cfg = $('Config').first().json;
const agg = $('Aggregate metrics').first().json;
const sla = $('Evaluate SLA').first().json;
const cmp = $('Compare to previous run').first().json;
const fleet = agg.fleet;

const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const duration = (ms) => (ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`);

const reasonText = {
  success: (wf) => `success ${wf.successRate}% < ${sla.targets.successRate}%`,
  latency: (wf) => `p95 ${duration(wf.p95Ms)} > ${sla.targets.p95Seconds}s`,
  availability: () => 'stalled',
};

const breaching = sla.perWorkflow
  .filter((wf) => wf.slaStatus === 'breached')
  .map((wf) => `  - ${wf.name}: ${wf.breachReasons.map((reason) => reasonText[reason](wf)).join(', ')}`);

const offenders = agg.perWorkflow
  .filter((wf) => wf.runs > 0 && wf.errors > 0)
  .sort((a, b) => b.errors - a.errors)
  .slice(0, 5)
  .map((wf) => `  - ${wf.name}: ${plural(wf.runs, 'run')}, ${wf.successRate}% ok, ${plural(wf.errors, 'error')}`);

const slowest = agg.perWorkflow
  .filter((wf) => wf.p95Ms !== null)
  .sort((a, b) => b.p95Ms - a.p95Ms)
  .slice(0, 3)
  .map((wf) => `  - ${wf.name}: ${duration(wf.p95Ms)} p95 over ${plural(wf.runs, 'run')}`);

const changes = [
  ...cmp.newlyBreaching.map((wf) => `  - new breach: ${wf.name} (${wf.reasons.join(', ')})`),
  ...cmp.recovered.map((wf) => `  - recovered: ${wf.name}`),
  ...cmp.slowdowns.map((wf) => `  - slower: ${wf.name} p95 +${wf.growthPct}%`),
  ...cmp.successDrops.map((wf) => `  - success drop: ${wf.name} -${wf.dropPp}pp`),
];

const delta = cmp.fleetSuccessDelta;
const deltaSuffix = delta != null ? ` (${delta >= 0 ? '+' : ''}${delta}pp vs last)` : '';

return [{ json: {
  date: cmp.runAt.slice(0, 10),
  windowHours: agg.windowHours,
  workflowsLine: plural(agg.workflowsTotal, 'workflow'),
  truncationLine: agg.windowTruncated
    ? `Note: hit the ${agg.executionLimit}-execution fetch limit, older runs may be cut off. Raise executionLimit in Config.`
    : '',
  targetsLine: `Targets: success >= ${sla.targets.successRate}%, p95 <= ${sla.targets.p95Seconds}s`,
  slaLine: `SLA: ${sla.metCount}/${sla.evaluatedCount} workflows meeting SLA`,
  fleetLine: `Fleet: ${plural(fleet.runs, 'run')}, ${fleet.successRate ?? 0}% success, ${plural(fleet.errors, 'error')}${deltaSuffix}`,
  breachingList: breaching.join('\n') || '  - none, all workflows within SLA',
  offendersList: offenders.join('\n') || '  - none, all green',
  slowestList: slowest.join('\n') || '  - no timing data',
  changesList: cmp.hasPrevious ? (changes.join('\n') || '  - no significant changes') : '  - first run, no comparison yet',
  breachCount: sla.breachCount,
  metCount: sla.metCount,
  evaluatedCount: sla.evaluatedCount,
} }];

